function schema_statements(string $prefix): array {
    if(!preg_match('/^[a-zA-Z][a-zA-Z0-9_]{1,19}$/D',$prefix)) throw new InvalidArgumentException('Invalid database prefix.');
    $t=fn($n)=>'`'.$prefix.$n.'`';$engine=' ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci';
    return [
        'settings'=>'CREATE TABLE '.$t('settings').' (name VARCHAR(100) PRIMARY KEY,value LONGTEXT NOT NULL)'.$engine,
        'users'=>'CREATE TABLE '.$t('users').' (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,auth_version VARCHAR(64) NOT NULL,created_at DATETIME NOT NULL,last_login DATETIME NULL)'.$engine,
        'projects'=>'CREATE TABLE '.$t('projects').' (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,slug VARCHAR(160) NOT NULL UNIQUE,title VARCHAR(160) NOT NULL,category VARCHAR(80) NOT NULL,summary TEXT NOT NULL,description LONGTEXT NOT NULL,challenge TEXT NOT NULL,solution TEXT NOT NULL,deliverables TEXT NOT NULL,cover VARCHAR(100) NOT NULL DEFAULT \'\',media_id CHAR(32) NULL,website_url VARCHAR(500) NOT NULL DEFAULT \'\',status VARCHAR(20) NOT NULL DEFAULT \'draft\',is_demo TINYINT NOT NULL DEFAULT 0,featured TINYINT NOT NULL DEFAULT 0,sort_order INT NOT NULL DEFAULT 0,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,INDEX publication(status,sort_order))'.$engine,
        'services'=>'CREATE TABLE '.$t('services').' (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,slug VARCHAR(100) NOT NULL UNIQUE,title VARCHAR(120) NOT NULL,summary TEXT NOT NULL,body LONGTEXT NOT NULL,icon VARCHAR(30) NOT NULL,sort_order INT NOT NULL DEFAULT 0,active TINYINT NOT NULL DEFAULT 1)'.$engine,
        'testimonials'=>'CREATE TABLE '.$t('testimonials').' (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,role VARCHAR(160) NOT NULL,quote TEXT NOT NULL,rating INT NOT NULL DEFAULT 5,published TINYINT NOT NULL DEFAULT 0,consent TINYINT NOT NULL DEFAULT 0,sort_order INT NOT NULL DEFAULT 0)'.$engine,
        'leads'=>'CREATE TABLE '.$t('leads').' (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,reference VARCHAR(20) NOT NULL UNIQUE,request_key CHAR(64) NOT NULL UNIQUE,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL,company VARCHAR(160) NOT NULL DEFAULT \'\',phone VARCHAR(80) NOT NULL DEFAULT \'\',service VARCHAR(100) NOT NULL,budget VARCHAR(100) NOT NULL,timeline VARCHAR(100) NOT NULL,message TEXT NOT NULL,consent TINYINT NOT NULL,ip_hash CHAR(64) NOT NULL,status VARCHAR(20) NOT NULL DEFAULT \'new\',notes TEXT NOT NULL,notification_status VARCHAR(30) NOT NULL DEFAULT \'not_configured\',created_at DATETIME NOT NULL,INDEX lead_status(status,created_at))'.$engine,
        'media'=>'CREATE TABLE '.$t('media').' (id CHAR(32) PRIMARY KEY,filename VARCHAR(80) NOT NULL,mime VARCHAR(60) NOT NULL,bytes INT UNSIGNED NOT NULL,width INT NOT NULL,height INT NOT NULL,original_name VARCHAR(190) NOT NULL,created_at DATETIME NOT NULL)'.$engine,
        'rate_limits'=>'CREATE TABLE '.$t('rate_limits').' (bucket CHAR(64) PRIMARY KEY,attempts INT UNSIGNED NOT NULL,expires BIGINT NOT NULL,INDEX expiry(expires))'.$engine,
        'resets'=>'CREATE TABLE '.$t('resets').' (token_hash CHAR(64) PRIMARY KEY,user_id INT UNSIGNED NOT NULL,expires BIGINT NOT NULL,INDEX reset_expiry(expires))'.$engine,
        'audit'=>'CREATE TABLE '.$t('audit').' (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL DEFAULT 0,action VARCHAR(80) NOT NULL,detail VARCHAR(400) NOT NULL,created_at DATETIME NOT NULL,INDEX audit_date(created_at))'.$engine,
    ] + studio_schema($prefix) + staff_schema($prefix) + support_schema($prefix) + catalog_schema($prefix) + payments_schema($prefix) + attempts_schema($prefix) + notifications_schema($prefix) + ledger_schema($prefix) + delivery_schema($prefix) + activity_schema($prefix) + mail_templates_schema($prefix) + mail_accounts_schema($prefix);
}
